describe('observedAlertProjectionToValue', () => {
  const value = {
    uid: 'value-uid',
    rule: { $ref: 'ref-rule' },
    problemKey: 'value-problemKey',
    status: 'value-status',
    summary: 'value-summary',
    link: 'value-link',
    firedAt: 'value-firedAt',
    resolvedAt: 'value-resolvedAt',
    lastNotifiedAt: 'value-lastNotifiedAt',
    version: 'value-version',
  } as any;

  it('returns null without projection', () => {
    expect(observedAlertProjectionToValue(null)).toBeNull();
    expect(observedAlertProjectionToValue(undefined)).toBeNull();
  });

  it('keeps a plain value', () => {
    expect(observedAlertProjectionToValue(value)).toEqual(value);
  });

  it('reduces the projected references to their key', () => {
    const projection = {
      uid: 'value-uid',
      rule: () => ({ uid: 'ref-rule' }),
      problemKey: 'value-problemKey',
      status: 'value-status',
      summary: 'value-summary',
      link: 'value-link',
      firedAt: 'value-firedAt',
      resolvedAt: 'value-resolvedAt',
      lastNotifiedAt: 'value-lastNotifiedAt',
      version: 'value-version',
    } as any;
    expect(observedAlertProjectionToValue(projection)).toEqual(value);
  });
});
